```csharp
public class Solution {
    public int[] HitBricks(int[][] grid, int[][] hits) {
        int m = grid.Length;
        int n = grid[0].Length;
        int top = m * n;
        int[] parent = new int[top + 1];
        int[] size = new int[top + 1];
        for (int i = 0; i <= top; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        foreach (var h in hits) {
            if (grid[h[0]][h[1]] == 1) grid[h[0]][h[1]] = 2;
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int id = i * n + j;
                    if (i == 0) Union(id, top);
                    if (i > 0 && grid[i - 1][j] == 1) Union(id, (i - 1) * n + j);
                    if (j > 0 && grid[i][j - 1] == 1) Union(id, i * n + j - 1);
                }
            }
        }

        int[] result = new int[hits.Length];
        int[] dr = { 1, -1, 0, 0 };
        int[] dc = { 0, 0, 1, -1 };

        for (int k = hits.Length - 1; k >= 0; k--) {
            int r = hits[k][0];
            int c = hits[k][1];
            if (grid[r][c] != 2) continue;
            int before = size[Find(top)];
            grid[r][c] = 1;
            int id = r * n + c;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                    Union(id, nr * n + nc);
                }
            }
            if (r == 0) Union(id, top);
            int after = size[Find(top)];
            int fallen = after - before - 1;
            result[k] = fallen > 0 ? fallen : 0;
        }

        return result;

        int Find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        void Union(int a, int b) {
            a = Find(a);
            b = Find(b);
            if (a == b) return;
            if (size[a] < size[b]) {
                int t = a; a = b; b = t;
            }
            parent[b] = a;
            size[a] += size[b];
        }
    }
}
```

