```csharp
public class Solution {
    public int Clumsy(int n) {
        long total = 0;
        long current = n;
        int op = 0; // 0: '*', 1: '/', 2: '+', 3: '-'
        for (int i = n - 1; i >= 1; i--) {
            switch (op) {
                case 0:
                    current *= i;
                    break;
                case 1:
                    current /= i;
                    break;
                case 2:
                    total += current;
                    current = i;
                    break;
                default:
                    total += current;
                    current = -i;
                    break;
            }
            op = (op + 1) & 3;
        }
        total += current;
        return (int)total;
    }
}
```

