using System.Collections.Generic;

public class Solution {
    public bool CanCross(int[] stones) {
        int n = stones.Length;

        // Pruning: reaching stone i-1 takes at most i-1 jumps, so the next
        // jump size is at most i; any larger consecutive gap is uncrossable.
        for (int i = 1; i < n; i++) {
            if (stones[i] - stones[i - 1] > i) return false;
        }

        // dp[position] = set of jump sizes that can land the frog on that stone
        Dictionary<int, HashSet<int>> dp = new Dictionary<int, HashSet<int>>(n);
        for (int i = 0; i < n; i++) dp[stones[i]] = new HashSet<int>();
        dp[0].Add(0); // virtual last jump of 0, so the first jump must be exactly 1

        int last = stones[n - 1];
        for (int i = 0; i < n; i++) {
            int pos = stones[i];
            foreach (int k in dp[pos]) {
                for (int step = k - 1; step <= k + 1; step++) {
                    if (step <= 0) continue;
                    long next = (long)pos + step;
                    if (next == last) return true;
                    if (next < last && dp.TryGetValue((int)next, out HashSet<int> set)) {
                        set.Add(step);
                    }
                }
            }
        }
        return false;
    }
}
```

