```csharp
using System.Collections.Generic;

public class Solution {
    public bool CanCross(int[] stones) {
        int n = stones.Length;

        // Pruning: the jump from stone i-1 to stone i can be at most i
        // (the frog makes at most i-1 jumps to reach stone i-1, and each
        // jump can grow by at most 1 from the initial jump of 1).
        for (int i = 1; i < n; i++) {
            if (stones[i] - stones[i - 1] > i) return false;
        }

        var dp = new Dictionary<int, HashSet<int>>();
        for (int i = 0; i < n; i++) dp[stones[i]] = new HashSet<int>();
        dp[0].Add(0);

        int last = stones[n - 1];
        for (int i = 0; i < n; i++) {
            int pos = stones[i];
            HashSet<int> jumps = dp[pos];
            if (jumps.Count == 0) continue;
            foreach (int k in jumps) {
                for (int step = k - 1; step <= k + 1; step++) {
                    if (step <= 0) continue;
                    long next = (long)pos + step;
                    if (next == last) return true;
                    if (next < last && dp.TryGetValue((int)next, out HashSet<int> set)) {
                        set.Add(step);
                    }
                }
            }
        }
        return false;
    }
}
```

