```csharp
using System.Collections.Generic;

public class Solution {
    public bool CanCross(int[] stones) {
        int n = stones.Length;

        // Pruning: to land on stone i-1 the frog makes at most i-1 jumps,
        // so the next jump is at most i; a larger gap is uncrossable.
        for (int i = 1; i < n; i++) {
            if (stones[i] - stones[i - 1] > i) return false;
        }

        // dp[pos] = set of jump sizes with which the frog can land on 'pos'
        var dp = new Dictionary<int, HashSet<int>>();
        for (int i = 0; i < n; i++) dp[stones[i]] = new HashSet<int>();
        dp[0].Add(0); // start: pretend last jump was 0, so first jump can be 1

        int last = stones[n - 1];
        for (int i = 0; i < n; i++) {
            int pos = stones[i];
            foreach (int k in dp[pos]) {
                for (int step = k - 1; step <= k + 1; step++) {
                    if (step <= 0) continue;
                    long next = (long)pos + step;
                    if (next == last) return true;
                    if (next < last && dp.TryGetValue((int)next, out var set)) {
                        set.Add(step);
                    }
                }
            }
        }
        return false;
    }
}
```

