using System;
using System.Collections.Generic;

public class Solution {
    private int[] nums;
    private int numSlots;
    private Dictionary<(int,int), int> memo;

    public int MaximumANDSum(int[] nums, int numSlots) {
        this.nums = nums;
        this.numSlots = numSlots;
        memo = new Dictionary<(int,int), int>();
        return Dp(0, 0);
    }

    private int Dp(int i, int mask) {
        if (i == nums.Length) return 0;
        var key = (i, mask);
        if (memo.TryGetValue(key, out int v)) return v;
        int best = 0;
        for (int slot = 0; slot < numSlots; slot++) {
            for (int half = 0; half < 2; half++) {
                int bit = slot * 2 + half;
                if ((mask & (1 << bit)) != 0) continue;
                int gain = nums[i] & (slot + 1);
                best = Math.Max(best, gain + Dp(i + 1, mask | (1 << bit)));
            }
        }
        memo[key] = best;
        return best;
    }
}
```

