```csharp
public class Solution {
    public int MaxEqualFreq(int[] nums) {
        var cnt = new int[100001];
        var freq = new int[100001];
        int maxF = 0;
        int ans = 0;
        for (int i = 0; i < nums.Length; i++) {
            int v = nums[i];
            int c = cnt[v];
            if (c > 0) freq[c]--;
            c++;
            cnt[v] = c;
            freq[c]++;
            if (c > maxF) maxF = c;
            int len = i + 1;
            if (maxF == 1 ||
                maxF * freq[maxF] == len - 1 ||
                (maxF - 1) * (freq[maxF - 1] + 1) == len - 1) {
                ans = len;
            }
        }
        return ans;
    }
}
```

