Let me write the C# code:

```csharp
using System.Collections.Generic;
using System.Text;

public class Solution {
    public string Evaluate(string s, IList<IList<string>> knowledge) {
        var dict = new Dictionary<string, string>();
        foreach (var pair in knowledge) {
            dict[pair[0]] = pair[1];
        }

        var sb = new StringBuilder();
        int n = s.Length;
        int i = 0;
        while (i < n) {
            if (s[i] == '(') {
                int j = i + 1;
                while (s[j] != ')') j++;
                string key = s.Substring(i + 1, j - i - 1);
                if (dict.TryGetValue(key, out var value)) {
                    sb.Append(value);
                } else {
                    sb.Append('?');
                }
                i = j + 1;
            } else {
                sb.Append(s[i]);
                i++;
            }
        }

        return sb.ToString();
    }
}
```

This is O(n + total knowledge size) time, which is efficient enough for the constraints (s.length up to 10^5, knowledge up to 10^5 entries).

