public class Solution {
    public long MaxRunTime(int n, int[] batteries) {
        long total = 0;
        foreach (int b in batteries) total += b;

        long lo = 1, hi = total / n;
        long ans = 0;
        while (lo <= hi) {
            long mid = lo + (hi - lo) / 2;
            if (Feasible(n, batteries, mid)) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans;
    }

    private bool Feasible(int n, int[] batteries, long t) {
        long need = (long)n * t;
        long sum = 0;
        foreach (int b in batteries) {
            sum += b < t ? b : t;
            if (sum >= need) return true;
        }
        return false;
    }
}
