public class Solution {
    public string LicenseKeyFormatting(string s, int k) {
        // Remove dashes and convert to uppercase
        var sb = new StringBuilder();
        foreach (char c in s) {
            if (c != '-') {
                sb.Append(char.ToUpper(c));
