using System;
using System.Collections.Generic;

public class Solution {
    public int MinMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.Length;
        bool[] infected = new bool[n];
        foreach (int x in initial) infected[x] = true;

        int[] parent = new int[n];
        int[] size = new int[n];
        for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }

        int Find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        for (int i = 0; i < n; i++) {
            if (infected[i]) continue;
            for (int j = i + 1; j < n; j++) {
                if (graph[i][j] == 1 && !infected[j]) {
                    int ri = Find(i), rj = Find(j);
                    if (ri != rj) {
                        parent[rj] = ri;
                        size[ri] += size[rj];
                    }
                }
            }
        }

        var touchCount = new Dictionary<int, int>();
        var nodeTouches = new Dictionary<int, HashSet<int>>();
        foreach (int x in initial) {
            var set = new HashSet<int>();
            for (int j = 0; j < n; j++) {
                if (graph[x][j] == 1 && !infected[j]) set.Add(Find(j));
            }
            nodeTouches[x] = set;
            foreach (int r in set) {
                if (touchCount.TryGetValue(r, out int c)) touchCount[r] = c + 1;
                else touchCount[r] = 1;
            }
        }

        int ans = -1, bestSaved = -1;
        foreach (int x in initial) {
            int saved = 0;
            foreach (int r in nodeTouches[x]) {
                if (touchCount[r] == 1) saved += size[r];
            }
            if (saved > bestSaved || (saved == bestSaved && x < ans)) {
                bestSaved = saved;
                ans = x;
            }
        }
        return ans;
    }
}
