public class Solution {
    public string MaximumBinaryString(string binary) {
        int n = binary.Length;
        int first = -1, zeros = 0;
        for (int i = 0; i < n; i++) {
            if (binary[i] == '0') {
                if (first < 0) first = i;
                zeros++;
            }
        }
        if (zeros == 0) return binary;
        int zeroPos = first + zeros - 1;
        char[] res = new char[n];
        for (int i = 0; i < n; i++) res[i] = '1';
        res[zeroPos] = '0';
        return new string(res);
    }
}
