public class Solution {
    public int MinDays(int[][] grid) {
        int m = grid.Length;
        int n = grid[0].Length;

        if (CountIslands(grid) != 1) return 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    grid[i][j] = 0;
                    int islands = CountIslands(grid);
                    grid[i][j] = 1;
                    if (islands != 1) return 1;
