    private int CountIslands(int[][] grid) {
        int m = grid.Length;
        int n = grid[0].Length;
        bool[,] visited = new bool[m, n];
        int count = 0;
        int[] dx = { 1, -1, 0, 0 };
        int[] dy = { 0, 0, 1, -1 };

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && !visited[i, j]) {
                    count++;
                    if (count >= 2) return count;
                    Queue<int> queue = new Queue<int>();
                    queue.Enqueue(i * n + j);
                    visited[i, j] = true;
                    while (queue.Count > 0) {
                        int cur = queue.Dequeue();
                        int x = cur / n;
                        int y = cur % n;
                        for (int k = 0; k < 4; k++) {
                            int nx = x + dx[k];
                            int ny = y + dy[k];
                            if (nx >= 0 && nx < m && ny >= 0 && ny < n &&
                                grid[nx][ny] == 1 && !visited[nx, ny]) {
                                visited[nx, ny] = true;
                                queue.Enqueue(nx * n + ny);
                            }
                        }
                    }
                }
            }
        }
        return count;
    }
}
