                if (grid[i][j] == 1) {
                    grid[i][j] = 0;
                    int islands = CountIslands(grid);
                    grid[i][j] = 1;
                    if (islands != 1) return 1;
                }
            }
        }
        return 2;
    }

    private int CountIslands(int[][] grid) {
        int m = grid.Length, n = grid[0].Length;
        bool[,] visited = new bool[m, n];
        int count = 0;
