            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && !visited[i, j]) {
                    count++;
                    if (count > 1) return count; // early exit optimization
                    // BFS/DFS
                    var queue = new Queue<(int, int)>();
                    queue.Enqueue((i, j));
                    visited[i, j] = true;
                    while (queue.Count > 0) {
                        var (x, y) = queue.Dequeue();
                        int[] dx = {1, -1, 0, 0};
