```csharp
public class Solution {
    public int MaxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.Length;
        int n = students[0].Length;

        // Precompute compatibility scores
        int[,] score = new int[m, m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int s = 0;
                for (int k = 0; k < n; k++) {
                    if (students[i][k] == mentors[j][k]) s++;
                }
                score[i, j] = s;
            }
        }

        // Bitmask DP
        int[] dp = new int[1 << m];
        for (int mask = 0; mask < (1 << m); mask++) {
            int k = PopCount(mask); // number of students already assigned
            if (k >= m) continue;
            for (int j = 0; j < m; j++) {
                if ((mask & (1 << j)) == 0) {
                    int newMask = mask | (1 << j);
                    int val = dp[mask] + score[k, j];
                    if (val > dp[newMask]) dp[newMask] = val;
                }
            }
        }

        return dp[(1 << m) - 1];
    }

    private int PopCount(int x) {
        int count = 0;
        while (x > 0) {
            x &= x - 1;
            count++;
        }
        return count;
    }
}
```

