public class Solution {
    public int MaxSumTwoNoOverlap(int[] nums, int firstLen, int secondLen) {
        int n = nums.Length;
        int[] pre = new int[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];

        int ans = 0;
        int L = firstLen, M = secondLen;

        // Case 1: firstLen subarray before secondLen subarray
        // second subarray occupies [j, j+M); first ends at index <= j-1
        int bestLeft = 0;
        for (int j = L; j + M <= n; j++) {
            int candidate = pre[j] - pre[j - L]; // length-L subarray ending at j-1
            if (candidate > bestLeft) bestLeft = candidate;
            int secondSum = pre[j + M] - pre[j];
            int total = bestLeft + secondSum;
            if (total > ans) ans = total;
        }

        // Case 2: secondLen subarray before firstLen subarray
        // second subarray occupies [j, j+M); first starts at index >= j+M
        int bestRight = 0;
        for (int j = n - M - L; j >= 0; j--) {
            int candidate = pre[j + M + L] - pre[j + M]; // length-L subarray starting at j+M
            if (candidate > bestRight) bestRight = candidate;
            int secondSum = pre[j + M] - pre[j];
            int total = bestRight + secondSum;
            if (total > ans) ans = total;
        }

        return ans;
    }
}
