    private int Days(string date) {
        int y = int.Parse(date.Substring(0, 4));
        int m = int.Parse(date.Substring(5, 2));
        int d = int.Parse(date.Substring(8, 2));
        int[] dm = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
        int total = d;
        for (int i = 0; i < m - 1; i++) total += dm[i];
        if (m > 2 && IsLeap(y)) total++;
        // add days for years
        total += (y - 1) * 365 + CountLeaps(y - 1);
        return total;
    }

    private bool IsLeap(int y) => (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);

    private int CountLeaps(int y) => y / 4 - y / 100 + y / 400;
}
```

