This is a classic Union-Find problem with restrictions checking.

Approach:
- Use Union-Find (DSU) data structure.
- For each request (u, v):
  - Find roots ru = find(u), rv = find(v).
  - If ru == rv, the request is successful (already friends).
  - Otherwise, check all restrictions: for each restriction (x, y), if find(x) and find(y) would end up in the same component after merging ru and rv (i.e., (root(x) == ru && root(y) == rv) || (root(x) == rv && root(y) == ru)), then the request fails.
  - If no restriction is violated, union ru and rv, and the request is successful.

Complexity: O(requests * restrictions * α) which is fine for n, requests, restrictions ≤ 1000.

Let me write the C# code:

```csharp
public class Solution {
    private int[] parent;

    public bool[] FriendRequests(int n, int[][] restrictions, int[][] requests) {
        parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        bool[] result = new bool[requests.Length];

        for (int j = 0; j < requests.Length; j++) {
            int u = requests[j][0], v = requests[j][1];
            int ru = Find(u), rv = Find(v);

            if (ru == rv) {
                result[j] = true;
                continue;
            }

            bool ok = true;
            foreach (var r in restrictions) {
                int rx = Find(r[0]), ry = Find(r[1]);
                if ((rx == ru && ry == rv) || (rx == rv && ry == ru)) {
                    ok = false;
                    break;
                }
            }

            if (ok) {
                parent[ru] = rv;
                result[j] = true;
            } else {
                result[j] = false;
            }
        }

        return result;
    }

    private int Find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
}
```

