```csharp
public class Solution {
    public int MinSessions(int[] tasks, int sessionTime) {
        int n = tasks.Length;
        int size = 1 << n;
        int[] sess = new int[size];
        int[] rem = new int[size];

        for (int mask = 1; mask < size; mask++) sess[mask] = int.MaxValue;
        sess[0] = 0;
        rem[0] = 0;

        for (int mask = 0; mask < size; mask++) {
            int s = sess[mask];
            if (s == int.MaxValue) continue;
            int r = rem[mask];

            for (int i = 0; i < n; i++) {
                int bit = 1 << i;
                if ((mask & bit) != 0) continue;
                int nm = mask | bit;

                int ns, nr;
                if (tasks[i] <= r) {
                    // fits into the current (last opened) session
                    ns = s;
                    nr = r - tasks[i];
                } else {
                    // must open a new session
                    ns = s + 1;
                    nr = sessionTime - tasks[i];
                }

                if (ns < sess[nm] || (ns == sess[nm] && nr > rem[nm])) {
                    sess[nm] = ns;
                    rem[nm] = nr;
                }
            }
        }

        return sess[size - 1];
    }
}
```

