```csharp
void dfs(string s, int index, int leftRem, int rightRem, int openCount, StringBuilder sb, HashSet<string> result) {
    if (index == s.Length) {
        if (leftRem == 0 && rightRem == 0 && openCount == 0) result.Add(sb.ToString());
        return;
    }
    char c = s[index];
    if (c == '(') {
        if (leftRem > 0) {
            // remove it
            dfs(s, index + 1, leftRem - 1, rightRem, openCount, sb, result);
        }
        // keep it
        sb.Append(c);
        dfs(s, index + 1, leftRem, rightRem, openCount + 1, sb, result);
        sb.Length--;
    } else if (c == ')') {
        if (rightRem > 0) {
            dfs(s, index + 1, leftRem, rightRem - 1, openCount, sb, result);
        }
        if (openCount > 0) {
            sb.Append(c);
            dfs(s, index + 1, leftRem, rightRem, openCount - 1, sb, result);
            sb.Length--;
        }
    } else {
        sb.Append(c);
        dfs(s, index + 1, leftRem, rightRem, openCount, sb, result);
        sb.Length--;
    }
}
