```csharp
public class Solution {
    private Dictionary<(int, int, int), bool> memo;
    private string s1, s2;

    public bool IsScramble(string s1, string s2) {
        this.s1 = s1;
        this.s2 = s2;
        memo = new Dictionary<(int, int, int), bool>();
        return Dfs(0, 0, s1.Length);
    }

    private bool Dfs(int i, int j, int len) {
        var key = (i, j, len);
        if (memo.ContainsKey(key)) return memo[key];

        string a = s1.Substring(i, len);
        string b = s2.Substring(j, len);
        if (a == b) { memo[key] = true; return true; }
        if (!SameChars(a, b)) { memo[key] = false; return false; }

        for (int k = 1; k < len; k++) {
            // no swap: s1[i..i+k) matches s2[j..j+k), s1[i+k..i+len) matches s2[j+k..j+len)
            if (Dfs(i, j, k) && Dfs(i + k, j + k, len - k)) { memo[key] = true; return true; }
            // swap: s1[i..i+k) matches s2[j+len-k..j+len), s1[i+k..i+len) matches s2[j..j+len-k)
            if (Dfs(i, j + len - k, k) && Dfs(i + k, j, len - k)) { memo[key] = true; return true; }
        }

        memo[key] = false;
        return false;
    }

    private bool SameChars(string a, string b) {
        int[] count = new int[26];
        foreach (char c in a) count[c - 'a']++;
        foreach (char c in b) {
            count[c - 'a']--;
            if (count[c - 'a'] < 0) return false;
        }
        return true;
    }
}
```

