```csharp
using System.Collections.Generic;

public class Solution {
    public int NumTriplets(int[] nums1, int[] nums2) {
        var sq1 = new Dictionary<long, long>();
        foreach (int x in nums1) {
            long sq = (long)x * x;
            sq1.TryGetValue(sq, out long c);
            sq1[sq] = c + 1;
        }
        var sq2 = new Dictionary<long, long>();
        foreach (int x in nums2) {
            long sq = (long)x * x;
            sq2.TryGetValue(sq, out long c);
            sq2[sq] = c + 1;
        }

        long total = CountPairs(nums2, sq1) + CountPairs(nums1, sq2);
        return (int)total;
    }

    private long CountPairs(int[] arr, Dictionary<long, long> sqCounts) {
        long total = 0;
        for (int j = 0; j < arr.Length; j++) {
            for (int k = j + 1; k < arr.Length; k++) {
                long product = (long)arr[j] * arr[k];
                if (sqCounts.TryGetValue(product, out long c)) {
                    total += c;
                }
            }
        }
        return total;
    }
}
```

