public class Solution {
    public double[] MedianSlidingWindow(int[] nums, int k) {
        int n = nums.Length;

        // Coordinate compression of all values
        int[] sorted = (int[])nums.Clone();
        Array.Sort(sorted);
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) sorted[m++] = sorted[i];
        }

        int[] tree = new int[m + 1];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) {
            rank[i] = Array.BinarySearch(sorted, 0, m, nums[i]) + 1; // 1-based compressed index
        }

        int LOG = 0;
        while ((1 << (LOG + 1)) <= m) LOG++;

        void Add(int idx, int d) {
            for (; idx <= m; idx += idx & -idx) tree[idx] += d;
        }

        // Find 1-based compressed index of the kk-th smallest element in current window
        int FindKth(int kk) {
            int pos = 0;
            for (int pw = 1 << LOG; pw > 0; pw >>= 1) {
                int np = pos + pw;
                if (np <= m && tree[np] < kk) {
                    pos = np;
                    kk -= tree[np];
                }
            }
            return pos + 1;
        }

        double[] res = new double[n - k + 1];

        for (int i = 0; i < k; i++) Add(rank[i], 1);

        bool odd = (k & 1) == 1;
        int lowerRank = (k + 1) / 2; // rank of lower median (1-based)
        int upperRank = k / 2 + 1;   // rank of upper median (1-based)

        for (int i = 0; i + k <= n; i++) {
            if (odd) {
                res[i] = sorted[FindKth(lowerRank) - 1];
            } else {
                long a = sorted[FindKth(lowerRank) - 1];
                long b = sorted[FindKth(upperRank) - 1];
                res[i] = (a + b) / 2.0;
            }
            if (i + k < n) {
                Add(rank[i], -1);
                Add(rank[i + k], 1);
            }
        }

        return res;
    }
}
