```csharp
public class Solution {
    public int SplitArray(int[] nums, int k) {
        long lo = 0, hi = 0;
        foreach (var x in nums) {
            hi += x;
            if (x > lo) lo = x;
        }
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (CanSplit(nums, k, mid)) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return (int)lo;
    }

    private bool CanSplit(int[] nums, int k, long cap) {
        int count = 1;
        long sum = 0;
        foreach (var x in nums) {
            if (sum + x > cap) {
                count++;
                sum = x;
                if (count > k) return false;
            } else {
                sum += x;
            }
        }
        return true;
    }
}
```

