```csharp
using System;
using System.Collections.Generic;

public class Solution {
    public int MinStickers(string[] stickers, string target) {
        int n = target.Length;
        int[] targetCount = new int[26];
        foreach (char ch in target) targetCount[ch - 'a']++;

        int[] posMask = new int[26];
        for (int i = 0; i < n; i++) posMask[target[i] - 'a'] |= 1 << i;

        var counts = new List<int[]>();
        var compacts = new List<int[]>();

        foreach (string s in stickers) {
            int[] cnt = new int[26];
            foreach (char ch in s) {
                int c = ch - 'a';
                if (targetCount[c] > 0) cnt[c]++;
            }
            bool useful = false;
            for (int i = 0; i < 26; i++) {
                if (cnt[i] > 0) { useful = true; break; }
            }
            if (!useful) continue;

            bool dominated = false;
            for (int j = 0; j < counts.Count; j++) {
                int[] other = counts[j];
                bool newDomsOld = true, oldDomsNew = true;
                for (int i = 0; i < 26; i++) {
                    if (cnt[i] < other[i]) newDomsOld = false;
                    if (other[i] < cnt[i]) oldDomsNew = false;
                }
                if (oldDomsNew) { dominated = true; break; }
                if (newDomsOld) {
                    counts.RemoveAt(j);
                    compacts.RemoveAt(j);
                    j--;
                }
            }
            if (dominated) continue;

            counts.Add(cnt);
            int d = 0;
            for (int i = 0; i < 26; i++) if (cnt[i] > 0) d++;
            int[] cp = new int[2 * d];
            int idx = 0;
            for (int i = 0; i < 26; i++) {
                if (cnt[i] > 0) { cp[idx++] = i; cp[idx++] = cnt[i]; }
            }
            compacts.Add(cp);
        }

        int size = 1 << n;
        int[] memo = new int[size];
        for (int i = 0; i < size; i++) memo[i] = -1;
        memo[0] = 0;

        int Dfs(int mask) {
            if (memo[mask] != -1) return memo[mask];
            int first = 0;
            while ((mask & (1 << first)) == 0) first++;
            int need = target[first] - 'a';
            int best = int.MaxValue;
            for (int si = 0; si < counts.Count; si++) {
                if (counts[si][need] == 0) continue;
                int[] cp = compacts[si];
                int newMask = mask;
                for (int p = 0; p < cp.Length; p += 2) {
                    int m = mask & posMask[cp[p]];
                    if (m == 0) continue;
                    int r = m;
                    int k = cp[p + 1];
                    for (int x = 0; x < k && r != 0; x++) r &= r - 1;
                    newMask &= ~(m ^ r);
                }
                int sub = Dfs(newMask);
                if (sub != int.MaxValue && sub + 1 < best) best = sub + 1;
            }
            memo[mask] = best;
            return best;
        }

        int ans = Dfs(size - 1);
        return ans == int.MaxValue ? -1 : ans;
    }
}
