Implementation:

```csharp
public class Solution {
    public int RegionsBySlashes(string[] grid) {
        int n = grid.Length;
        int N = 3 * n;
        int[][] g = new int[N][];
        for (int i = 0; i < N; i++) g[i] = new int[N]; // 0 = open, 1 = wall

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                char c = grid[i][j];
                if (c == '/') {
                    g[3*i][3*j+2] = 1;
                    g[3*i+1][3*j+1] = 1;
                    g[3*i+2][3*j] = 1;
                } else if (c == '\\') {
                    g[3*i][3*j] = 1;
                    g[3*i+1][3*j+1] = 1;
                    g[3*i+2][3*j+2] = 1;
                }
            }
        }

        int regions = 0;
        bool[][] visited = new bool[N][];
        for (int i = 0; i < N; i++) visited[i] = new bool[N];

        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (g[i][j] == 0 && !visited[i][j]) {
                    regions++;
                    // BFS
                    var queue = new Queue<(int,int)>();
                    queue.Enqueue((i,j));
                    visited[i][j] = true;
                    while (queue.Count > 0) {
                        var (r, c) = queue.Dequeue();
                        for (int d = 0; d < 4; d++) {
                            int nr = r + dr[d], nc = c + dc[d];
                            if (nr >= 0 && nr < N && nc >= 0 && nc < N && g[nr][nc] == 0 && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                queue.Enqueue((nr, nc));
                            }
                        }
                    }
                }
            }
        }

        return regions;
    }
}
```

