Looking at this problem:

- The state of any round can be fully described by `(m, i, j)`: the current number of players `m`, the position `i` of `firstPlayer`, and position `j` of `secondPlayer` (the row is always sorted by player number, so positions = ranks). All other players are interchangeable.
- If `i + j == m + 1`, they compete **this** round → return `(1, 1)`.
- Otherwise both specials win their matches. Each normal pair `(k, m+1-k)` yields exactly one survivor (we choose which), and if `m` is odd the middle player (if normal) auto-advances. Survivors total `ceil(m/2)`.
- Each survivor falls into one of three regions: before `i`, between `i` and `j`, or after `j`. If the counts are `(c1, c2, c3)`, the next state is `m' = c1+c2+c3+2`, `i' = c1+1`, `j' = c1+c2+2`.
- Enumerate all choice combinations (at most 2^12 for m=28), dedupe resulting counts, and recurse: earliest = 1 + min over children, latest = 1 + max over children. Memoize on `(m,i,j)`.

I verified this against both examples (n=11 → [3,4], n=5 → [1,1]) and several hand-traced cases (n=3..7).

```csharp
using System;
using System.Collections.Generic;

public class Solution {
    public int[] EarliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        var memo = new Dictionary<(int, int, int), int[]>();
        return Solve(n, firstPlayer, secondPlayer, memo);
    }

    private int[] Solve(int m, int i, int j, Dictionary<(int, int, int), int[]> memo) {
        if (i + j == m + 1) return new int[] { 1, 1 };
        var key = (m, i, j);
        if (memo.TryGetValue(key, out int[] cached)) return cached;

        int[] cnt = new int[3];
        if (m % 2 == 1) {
            int h = (m + 1) / 2;
            if (h != i && h != j) cnt[RegionOf(h, i, j)] = 1;
        }

        var pairs = new List<int[]>();
        for (int k = 1; k <= m / 2; k++) {
            int b = m + 1 - k;
            if (k == b) continue;
            if (k == i || b == i || k == j || b == j) continue;
            pairs.Add(new int[] { RegionOf(k, i, j), RegionOf(b, i, j) });
        }

        var seen = new HashSet<(int, int, int)>();
        Collect(pairs, 0, cnt, seen);

        int bestE = int.MaxValue, bestL = int.MinValue;
        foreach (var s in seen) {
            int nm = s.Item1 + s.Item2 + s.Item3 + 2;
            int ni = s.Item1 + 1;
            int nj = s.Item1 + s.Item2 + 2;
            int[] r = Solve(nm, ni, nj, memo);
            if (r[0] + 1 < bestE) bestE = r[0] + 1;
            if (r[1] + 1 > bestL) bestL = r[1] + 1;
        }

        int[] ans = { bestE, bestL };
        memo[key] = ans;
        return ans;
    }

    private void Collect(List<int[]> pairs, int idx, int[] cur, HashSet<(int, int, int)> seen) {
        if (idx == pairs.Count) {
            seen.Add((cur[0], cur[1], cur[2]));
            return;
        }
        for (int c = 0; c < 2; c++) {
            int[] nxt = { cur[0], cur[1], cur[2] };
            nxt[pairs[idx][c]]++;
            Collect(pairs, idx + 1, nxt, seen);
        }
    }

    private int RegionOf(int p, int i, int j) {
        if (p < i) return 0;
        if (p < j) return 1;
        return 2;
    }
}
