public class Solution {
    public int SumOddLengthSubarrays(int[] arr) {
        int n = arr.Length;
        int sum = 0;
        for (int i = 0; i < n; i++) {
            // Total number of subarrays containing arr[i]:
            // (i + 1) choices for the left endpoint, (n - i) choices for the right endpoint.
            int total = (i + 1) * (n - i);
            // Exactly half (rounded up) of those subarrays have odd length.
            int oddCount = (total + 1) / 2;
            sum += arr[i] * oddCount;
        }
        return sum;
    }
}
