```csharp
using System;
using System.Collections.Generic;

public class Solution {
    public int[] GetCoprimes(int[] nums, int[][] edges) {
        int n = nums.Length;
        List<int>[] adj = new List<int>[n];
        for (int i = 0; i < n; i++) adj[i] = new List<int>();
        foreach (var e in edges) {
            adj[e[0]].Add(e[1]);
            adj[e[1]].Add(e[0]);
        }

        bool[][] cop = new bool[51][];
        for (int a = 1; a <= 50; a++) {
            cop[a] = new bool[51];
            for (int b = 1; b <= 50; b++) {
                cop[a][b] = Gcd(a, b) == 1;
            }
        }

        int[] ans = new int[n];
        int[] lastDepth = new int[51];
        int[] lastNode = new int[51];
        for (int v = 0; v <= 50; v++) lastDepth[v] = -1;

        int[] depth = new int[n];
        int[] parent = new int[n];

        int[] stack = new int[2 * n];
        int top = 0;
        int[] rDepth = new int[n];
        int[] rNode = new int[n];
        int rTop = 0;

        parent[0] = -1;
        depth[0] = 0;
        stack[top++] = 0;

        while (top > 0) {
            int cur = stack[--top];
            if (cur >= n) {
                int node = cur - n;
                int val = nums[node];
                lastDepth[val] = rDepth[--rTop];
                lastNode[val] = rNode[rTop];
                continue;
            }

            int v = nums[cur];
            int bestDepth = -1, bestNode = -1;
            for (int u = 1; u <= 50; u++) {
                if (cop[v][u] && lastDepth[u] > bestDepth) {
                    bestDepth = lastDepth[u];
                    bestNode = lastNode[u];
                }
            }
            ans[cur] = bestNode;

            rDepth[rTop] = lastDepth[v];
            rNode[rTop] = lastNode[v];
            rTop++;
            lastDepth[v] = depth[cur];
            lastNode[v] = cur;

            stack[top++] = cur + n;
            foreach (int nb in adj[cur]) {
                if (nb != parent[cur]) {
                    parent[nb] = cur;
                    depth[nb] = depth[cur] + 1;
                    stack[top++] = nb;
                }
            }
        }

        return ans;
    }

    private int Gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}
