Looking at this problem, I need to solve a cryptarithmetic puzzle. My approach is column-wise backtracking from the least significant digit:

1. **Setup**: Reverse all words and the result so index 0 = least significant digit. Map each distinct character to an id. Mark characters that can't be zero (first character of any multi-character word/result — single-character strings have no leading zeros by definition).
2. **Backtracking by column**: For each column, process word characters (assigning digits to new ones, trying all unused digits), then check the result character: the column sum mod 10 must equal the result character's digit (assigning it if new, requiring the digit unused and non-zero if it's a leading char), with carry = sum / 10 propagated to the next column.
3. **Termination**: After the last column, the carry must be 0. If a column is beyond the result's length, the sum's digit there must be 0 (result padded with leading zeros).

I verified this against all three examples (e.g., SEND+MORE=MONEY: col0 D+E=12→Y=2 carry 1; col1 N+R+1=15→E=5; col2 E+O+1=6→N=6; col3 S+M=10→O=0 carry 1; col4 carry 1→M=1, final carry 0 → true), and the pruning (digit conflicts, leading zeros, carry checks) keeps the search tiny given ≤10 distinct characters.

```csharp
using System;
using System.Collections.Generic;

public class Solution {
    public bool IsSolvable(string[] words, string result) {
        int resultLen = result.Length;

        int maxLen = resultLen;
        foreach (string w in words) {
            if (w.Length > maxLen) maxLen = w.Length;
        }

        int[] id = new int[26];
        for (int i = 0; i < 26; i++) id[i] = -1;
        int cnt = 0;
        foreach (string w in words) {
            foreach (char ch in w) {
                int k = ch - 'A';
                if (id[k] < 0) id[k] = cnt++;
            }
        }
        foreach (char ch in result) {
            int k = ch - 'A';
            if (id[k] < 0) id[k] = cnt++;
        }

        bool[] nonZero = new bool[cnt];
        foreach (string w in words) {
            if (w.Length > 1) nonZero[id[w[0] - 'A']] = true;
        }
        if (resultLen > 1) nonZero[id[result[0] - 'A']] = true;

        int[][] colChars = new int[maxLen][];
        List<int>[] buckets = new List<int>[maxLen];
        for (int i = 0; i < maxLen; i++) buckets[i] = new List<int>();
        foreach (string w in words) {
            for (int i = 0; i < w.Length; i++) {
                buckets[w.Length - 1 - i].Add(id[w[i] - 'A']);
            }
        }
        for (int i = 0; i < maxLen; i++) colChars[i] = buckets[i].ToArray();

        int[] resChar = new int[resultLen];
        for (int i = 0; i < resultLen; i++) {
            resChar[i] = id[result[resultLen - 1 - i] - 'A'];
        }

        int[] digit = new int[cnt];
        bool[] assigned = new bool[cnt];
        bool[] usedDigit = new bool[10];

        bool Solve(int col, int idx, int sum) {
            if (col == maxLen) return sum == 0;
            int[] cs = colChars[col];
            if (idx < cs.Length) {
                int c = cs[idx];
                if (assigned[c]) return Solve(col, idx + 1, sum + digit[c]);
                bool mustNonZero = nonZero[c];
                for (int d = 0; d < 10; d++) {
                    if (usedDigit[d] || (mustNonZero && d == 0)) continue;
                    usedDigit[d] = true;
                    assigned[c] = true;
                    digit[c] = d;
                    if (Solve(col, idx + 1, sum + d)) return true;
                    usedDigit[d] = false;
                    assigned[c] = false;
                }
                return false;
            }
            int rd = sum % 10;
            int carry = sum / 10;
            if (col < resultLen) {
                int rc = resChar[col];
                if (assigned[rc]) {
                    return digit[rc] == rd && Solve(col + 1, 0, carry);
                }
                if (rd == 0 && nonZero[rc]) return false;
                if (usedDigit[rd]) return false;
                usedDigit[rd] = true;
                assigned[rc] = true;
                digit[rc] = rd;
                bool ok = Solve(col + 1, 0, carry);
                usedDigit[rd] = false;
                assigned[rc] = false;
                return ok;
            }
            if (rd != 0) return false;
            return Solve(col + 1, 0, carry);
        }

        return Solve(0, 0, 0);
    }
}
```

