```csharp
public class Solution {
    public bool IsSolvable(string[] words, string result) {
        int n = words.Length;
        // reversed words
        var revWords = new char[n][];
        var wordLens = new int[n];
        for (int i = 0; i < n; i++) {
            wordLens[i] = words[i].Length;
            revWords[i] = words[i].ToCharArray();
            Array.Reverse(revWords[i]);
        }
        int resultLen = result.Length;
        var revResult = result.ToCharArray();
        Array.Reverse(revResult);
        int maxLen = 0;
        for (int i = 0; i < n; i++) maxLen = Math.Max(maxLen, wordLens[i]);
        maxLen = Math.Max(maxLen, resultLen);

        // char id mapping
        var id = new int[26];
        Array.Fill(id, -1);
        int charCount = 0;
        foreach (var w in revWords) foreach (var c in w) if (id[c-'A'] < 0) id[c-'A'] = charCount++;
        foreach (var c in revResult) if (id[c-'A'] < 0) id[c-'A'] = charCount++;

        // leading chars (non-zero)
        var leading = new bool[charCount];
        foreach (var w in words) if (w.Length > 1) leading[id[w[0]-'A']] = true;
        if (resultLen > 1) leading[id[result[0]-'A']] = true;

        var digit = new int[charCount];
        var assigned = new bool[charCount];
        var usedDigit = new bool[10];

        // Solve(col, wordIdx, sum)
        // returns bool

        bool Solve(int col, int wordIdx, int sum) {
            if (wordIdx == n) {
                int d = sum % 10;
                int carry = sum / 10;
                if (col < resultLen) {
                    int rc = id[revResult[col]-'A'];
                    if (assigned[rc]) {
                        if (digit[rc] != d) return false;
                        if (col + 1 == maxLen) return carry == 0;
                        return Solve(col+1, 0, carry);
                    } else {
                        if (leading[rc] && d == 0) return false;
                        if (usedDigit[d]) return false;
                        assigned[rc] = true; usedDigit[d] = true; digit[rc] = d;
                        bool ok;
                        if (col + 1 == maxLen) ok = carry == 0;
                        else ok = Solve(col+1, 0, carry);
                        assigned[rc] = false; usedDigit[d] = false;
                        return ok;
                    }
                } else {
                    if (d != 0) return false;
                    if (col + 1 == maxLen) return carry == 0;
                    return Solve(col+1, 0, carry);
                }
            }
            if (col < wordLens[wordIdx]) {
                int c = id[revWords[wordIdx][col]-'A'];
                if (assigned[c]) {
                    return Solve(col, wordIdx+1, sum + digit[c]);
                } else {
                    for (int dv = 0; dv <= 9; dv++) {
                        if (usedDigit[dv]) continue;
                        if (leading[c] && dv == 0) continue;
                        usedDigit[dv] = true; assigned[c] = true; digit[c] = dv;
                        if (Solve(col, wordIdx+1, sum + dv)) return true;
                        usedDigit[dv] = false; assigned[c] = false;
                    }
                    return false;
                }
            } else {
                return Solve(col, wordIdx+1, sum);
            }
        }

        return Solve(0, 0, 0);
    }
}
```

