using System;
using System.Collections.Generic;

public class Solution {
    public bool IsSolvable(string[] words, string result) {
        int resultLen = result.Length;

        int maxLen = resultLen;
        foreach (string w in words)
            if (w.Length > maxLen) maxLen = w.Length;

        // Assign an id to each distinct character.
        int[] id = new int[26];
        for (int i = 0; i < 26; i++) id[i] = -1;
        int cnt = 0;
        foreach (string w in words)
            foreach (char ch in w) {
                int k = ch - 'A';
                if (id[k] < 0) id[k] = cnt++;
            }
        foreach (char ch in result) {
            int k = ch - 'A';
            if (id[k] < 0) id[k] = cnt++;
        }

        // Characters that may not be zero: leading characters of multi-character strings.
        bool[] nonZero = new bool[cnt];
        foreach (string w in words)
            if (w.Length > 1) nonZero[id[w[0] - 'A']] = true;
        if (resultLen > 1) nonZero[id[result[0] - 'A']] = true;

        // For each column (least significant first), list word characters in that column.
        int[][] colChars = new int[maxLen][];
        List<int>[] buckets = new List<int>[maxLen];
        for (int i = 0; i < maxLen; i++) buckets[i] = new List<int>();
        foreach (string w in words)
            for (int i = 0; i < w.Length; i++)
                buckets[w.Length - 1 - i].Add(id[w[i] - 'A']);
        for (int i = 0; i < maxLen; i++) colChars[i] = buckets[i].ToArray();

        // Result character for each column.
        int[] resChar = new int[resultLen];
        for (int i = 0; i < resultLen; i++)
            resChar[i] = id[result[resultLen - 1 - i] - 'A'];

        int[] digit = new int[cnt];
        bool[] assigned = new bool[cnt];
        bool[] usedDigit = new bool[10];

        bool Solve(int col, int idx, int sum) {
            if (col == maxLen) return sum == 0;
            int[] cs = colChars[col];
            if (idx < cs.Length) {
                int c = cs[idx];
                if (assigned[c]) return Solve(col, idx + 1, sum + digit[c]);
                bool mustNonZero = nonZero[c];
                for (int d = 0; d < 10; d++) {
                    if (usedDigit[d] || (mustNonZero && d == 0)) continue;
                    usedDigit[d] = true;
                    assigned[c] = true;
                    digit[c] = d;
                    if (Solve(col, idx + 1, sum + d)) return true;
                    usedDigit[d] = false;
                    assigned[c] = false;
                }
                return false;
            }
            int rd = sum % 10;
            int carry = sum / 10;
            if (col < resultLen) {
                int rc = resChar[col];
                if (assigned[rc]) {
                    if (digit[rc] != rd) return false;
                    return Solve(col + 1, 0, carry);
                }
                if (rd == 0 && nonZero[rc]) return false;
                if (usedDigit[rd]) return false;
                usedDigit[rd] = true;
                assigned[rc] = true;
                digit[rc] = rd;
                bool ok = Solve(col + 1, 0, carry);
                usedDigit[rd] = false;
                assigned[rc] = false;
                return ok;
            }
            if (rd != 0) return false;
            return Solve(col + 1, 0, carry);
        }

        return Solve(0, 0, 0);
    }
}
