```csharp
public class Solution {
    public string StrWithout3a3b(int a, int b) {
        var sb = new System.Text.StringBuilder(a + b);
        while (a > 0 || b > 0) {
            int n = sb.Length;
            bool writeA;
            if (n >= 2 && sb[n - 1] == sb[n - 2]) {
                writeA = sb[n - 1] == 'b';
            } else {
                writeA = a >= b;
            }
            if (writeA) {
                sb.Append('a');
                a--;
            } else {
                sb.Append('b');
                b--;
            }
        }
        return sb.ToString();
    }
}
