public class Solution {
    public bool IsMatch(string s, string p) {
        int i = 0, j = 0;
        int starIdx = -1, match = 0;
        int n = s.Length, m = p.Length;

        while (i < n) {
            if (j < m && (p[j] == '?' || p[j] == s[i])) {
                i++;
                j++;
            } else if (j < m && p[j] == '*') {
                starIdx = j;
                match = i;
                j++;
            } else if (starIdx != -1) {
                j = starIdx + 1;
                match++;
                i = match;
            } else {
                return false;
            }
        }

        while (j < m && p[j] == '*') {
            j++;
        }

        return j == m;
    }
}
```

